<script type="module">
const q = s => document.querySelector(s);
const val = s => (q(s).value || '').trim();
let pov = '第二人称';

document.querySelectorAll('#pov .chip').forEach(c => {
  c.addEventListener('click', () => {
    document.querySelectorAll('#pov .chip').forEach(x => x.classList.remove('on'));
    c.classList.add('on');
    pov = c.dataset.v;
  });
});

function collect() {
  const age = parseInt(val('#f-age'), 10);
  return {
    pov,
    era: val('#f-era'),
    name: val('#f-name') || '无名',
    surname: val('#f-surname') || '无',
    sex: val('#f-sex'),
    age: isNaN(age) ? 20 : Math.max(6, Math.min(80, age)),
    origin: val('#f-origin') || '平民',
    identity: val('#f-identity') || '平民',
    bg: val('#f-bg'),
    place: val('#f-place') || '北境·临冬城',
    gold: parseInt(val('#f-gold'), 10) || 0,
    silver: parseInt(val('#f-silver'), 10) || 0,
    copper: parseInt(val('#f-copper'), 10) || 0,
    weapon: val('#f-weapon') || '无',
    armor: val('#f-armor') || '无',
    mount: val('#f-mount') || '无',
    other: val('#f-other') || '无',
  };
}

function build(d) {
  return [
    '【开局】',
    '人称：' + d.pov,
    '纪元：' + d.era,
    '名字：' + d.name,
    '姓氏：' + d.surname,
    '性别：' + d.sex,
    '年龄：' + d.age,
    '出身：' + d.origin,
    '身份：' + d.identity,
    '地点：' + d.place,
    '金钱：金龙' + d.gold + ' 银鹿' + d.silver + ' 铜分币' + d.copper,
    '装备：武器=' + d.weapon + '；护甲=' + d.armor + '；坐骑=' + d.mount + '；其他=' + d.other,
    '背景：' + d.bg,
  ].join('\n');
}

async function copyText(t) {
  try {
    await navigator.clipboard.writeText(t);
    return true;
  } catch (e) {
    const ta = document.createElement('textarea');
    ta.value = t; document.body.appendChild(ta); ta.select();
    const ok = document.execCommand('copy');
    document.body.removeChild(ta);
    return ok;
  }
}

q('#btn-start').addEventListener('click', async () => {
  const err = q('#err'), btn = q('#btn-start');
  err.textContent = '';
  const d = collect();
  if (!d.bg) { err.textContent = '请先写一段背景。'; return; }

  const text = build(d);
  btn.disabled = true; btn.textContent = '推 演 中';

  try {
    if (typeof createChatMessages !== 'function') throw new Error('no-tavern-helper');
    await createChatMessages([{ role: 'user', message: text }]);
    await triggerSlash('/trigger');
  } catch (e) {
    const ok = await copyText(text);
    err.textContent = ok
      ? '已复制到剪贴板：请直接粘贴发送。'
      : '复制失败，请手动抄写下方内容。';
    const box = document.createElement('textarea');
