<div class="bar">
  <div class="row">
    <span class="k">此时</span>
    <span class="v" id="s-date">—</span>
    <span class="v" id="s-time">—</span>
    <span class="v dim" id="s-place">—</span>
  </div>
  <div class="row">
    <span class="k">其人</span>
    <span class="v" id="s-name">—</span>
    <span class="v dim" id="s-identity">—</span>
    <span class="v" id="s-health">—</span>
  </div>
  <div class="row">
    <span class="k">行囊</span>
    <span class="v gold" id="s-money">—</span>
    <span class="v dim" id="s-gear">—</span>
  </div>
  <div class="row" id="row-known" style="display:none">
    <span class="k">相识</span>
    <span class="v dim" id="s-known"></span>
  </div>
</div>
<script type="module">
/* 优先读最新楼层的 stat_data；读不到再退回合并变量表 */
function readState() {
  try {
    if (typeof getVariables === 'function') {
      const m = getVariables({ type: 'message', message_id: -1 });
      if (m && m.stat_data) return m.stat_data;
    }
  } catch (e) { /* ignore */ }
  try {
    if (typeof getAllVariables === 'function') {
      const v = getAllVariables() || {};
      return v.stat_data || v;
    }
  } catch (e) { /* ignore */ }
  return {};
}
function get(path) {
  return path.split('.').reduce((o, k) => (o == null ? undefined : o[k]), readState());
}
function set(id, text, cls) {
  const el = document.getElementById(id);
  if (!el) return;
  if (text !== undefined && text !== null && text !== '') el.textContent = text;
  if (cls) el.className = cls;
}
function render() {
  const p = get('主角') || {};
  /* 变量还没初始化时不显示，避免开场白里出现一整排「—」 */
  const bar = document.querySelector('.bar');
  const ready = !!(get('系统.日期') || p.名字);
  if (bar) bar.style.display = ready ? '' : 'none';
  if (!ready) return;

  set('s-date', get('系统.日期'));
  set('s-time', get('系统.时间'));
  set('s-place', get('系统.地点'));

  const full = [p.名字, p.姓氏].filter(x => x && x !== '无').join('·');
  set('s-name', full || p.名字 || '');
  set('s-identity', p.身份);

  const h = p.健康 || '';
  const hcls = (h === '健康') ? 'v'
    : (h === '重伤' || h === '濒死' || h === '已故') ? 'v bad' : 'v warn';
  set('s-health', h, hcls);

  const m = p.金钱 || {};
  set('s-money', (m.金龙 || 0) + ' 金 · ' + (m.银鹿 || 0) + ' 银 · ' + (m.铜分币 || 0) + ' 铜');

  const e = p.装备 || {};
  const gear = [e.武器, e.护甲, e.坐骑].filter(x => x && x !== '无');
  set('s-gear', gear.length ? gear.join(' / ') : '空手');

  const known = get('已识之人') || {};
  const names = Object.keys(known);
  if (names.length) {
    document.getElementById('row-known').style.display = '';
    set('s-known', names.slice(0, 6).join('、') + (names.length > 6 ? ' 等 ' + names.length + ' 人' : ''));
  }
}
render();

/* 任何会改变变量的时机都重绘 */
try {
  if (typeof eventOn === 'function') {
    if (typeof tavern_events !== 'undefined') {
      ['MESSAGE_RECEIVED', 'MESSAGE_UPDATED', 'MESSAGE_SWIPED', 'GENERATION_ENDED']
        .forEach(k => { if (tavern_events[k] !== undefined) eventOn(tavern_events[k], render); });
    }
    if (typeof Mvu !== 'undefined' && Mvu.events && Mvu.events.VARIABLE_UPDATE_ENDED) {
      eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, render);
    }
  }
} catch (e) { /* 无扩展时静默降级 */ }
</script>
</body>
</html>
