import { registerMvuSchema } from 'https://fastly.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

export const Schema = z.object({
  系统: z.object({
    时间: z.string().describe('HH:MM'),
    日期: z.string().describe('YYYY/MM/DD，伊耿历'),
    地点: z.string().describe('区域·具体地点，例如 北境·临冬城'),
    纪元: z.string().describe('承平之末 / 五王之战 / 血色之后 / 龙之母'),
    人称: z.string().describe('第一人称 / 第二人称 / 第三人称'),
  }),

  主角: z.object({
    名字: z.string(),
    姓氏: z.string().describe('无姓氏者填 无'),
    年龄: z.coerce.number(),
    性别: z.string(),
    身份: z.string(),
    背景: z.string().describe('玩家自己写的出身与来历'),
    健康: z.string().describe('健康 / 负伤 / 重伤 / 濒死 / 已故'),
    金钱: z.object({
      金龙: z.coerce.number(),
      银鹿: z.coerce.number(),
      铜分币: z.coerce.number(),
    }),
    装备: z.object({
      武器: z.string(),
      护甲: z.string(),
      坐骑: z.string(),
      其他: z.string(),
    }),
  }),

  已识之人: z.record(
    z.string().describe('姓名'),
    z.object({
      身份: z.string(),
      态度: z.string().describe('用文字描述，不写数字'),
    })
  ).prefault({}),
});

$(() => {
  registerMvuSchema(Schema);
})
